return $items().flatMap(item => {
  const original = String(item.json.phone ?? "").replace(/\D/g, "");

  if (!original) {
    return [{
      json: {
        ...item.json,
        phone: "",
        original_phone: ""
      }
    }];
  }

  // remove 55 pra facilitar lógica
  let country = "";
  let number = original;

  if (number.startsWith("55")) {
    country = "55";
    number = number.slice(2);
  }

  // DDD (2 primeiros)
  const ddd = number.slice(0, 2);
  let restante = number.slice(2);

  let com9, sem9;

  if (restante.startsWith("9")) {
    com9 = restante;
    sem9 = restante.slice(1);
  } else {
    sem9 = restante;
    com9 = "9" + restante;
  }

  const numeroCom9 = country + ddd + com9;
  const numeroSem9 = country + ddd + sem9;

  // evita duplicados
  const numeros = [...new Set([original, numeroCom9, numeroSem9])];

  return numeros.map(num => ({
    json: {
      ...item.json,
      phone: num,
      original_phone: original
    }
  }));
});

const seen = new Set();

return $items()
  .map(i => i.json)
  .filter(i => i && i.data && i.data.wuid) // remove vazios
  .filter(i => {
    // 🔥 MESMA LÓGICA, só mudamos o ID
    let id = String(i.data.wuid)
      .replace("@s.whatsapp.net", "")
      .replace("@c.us", "")
      .replace(/\D/g, "");

    // remove o 9 extra (BR)
    if (id.startsWith("55") && id.length === 13 && id[4] === "9") {
      id = id.slice(0, 4) + id.slice(5);
    }

    if (seen.has(id)) return false;
    seen.add(id);
    return true;
  })
  .map(i => {
    const data = i.data;

    const originalRaw = (i.original_phone ?? data.original_phone ?? null);
    const original_phone =
      originalRaw === null || originalRaw === undefined || String(originalRaw).trim() === ""
        ? null
        : String(originalRaw).replace(/\D/g, "");

    const rowRaw = (i.row_number ?? data.row_number ?? null);
    const row_number =
      rowRaw === null || rowRaw === undefined || String(rowRaw).trim() === ""
        ? null
        : Number(rowRaw);

    const razao = i.razao ?? data.razao ?? "";
    const cnpj = i.cnpj ?? data.cnpj ?? "";
    const observacao = i.observacao ?? data.observacao ?? "";

    return {
      json: {
        wuid: data.wuid,
        numberExists: data.numberExists,

        razao,
        cnpj: String(cnpj),
        observacao,

        ...(data.picture ? { picture: data.picture } : {}),

        ...(data.status && data.status.status && String(data.status.status).trim()
          ? { status: String(data.status.status).trim() }
          : {}),

        ...(data.isBusiness !== undefined
          ? { isBusiness: data.isBusiness }
          : {}),

        ...(original_phone ? { original_phone } : {}),
        ...(row_number !== null && !Number.isNaN(row_number) ? { row_number } : {})
      }
    };
  });

